    // weights (e.g. Q1_0 64x1) are handled by tensor traits and return
    // early, so counting inside the switch below would skip them
    static int andesim_mul_mat_n = 0;
    // resolved once; single-threaded like the counter above (the runbook uses -t 1)
    static int andesim_roi_first = 0, andesim_roi_last = 0;
