        // leaves it set and the whole A/B would be void with no other symptom.
        {
            uint64_t before, after;
            __asm__ volatile("csrr %0, 0x7CA" : "=r"(before));
            __asm__ volatile("csrc 0x7CA, %0" :: "r"((uint64_t) 0x400));
            __asm__ volatile("csrr %0, 0x7CA" : "=r"(after));
            fprintf(stderr, "[roi] mcache_ctl 0x%llx -> 0x%llx : DPREF_EN %d -> %d\n",
                    (unsigned long long) before, (unsigned long long) after,
                    (int) ((before >> 10) & 1), (int) ((after >> 10) & 1));
